package com.careerpilot.modules.interview.controller;import com.careerpilot.modules.interview.dto.InterviewDtos.*;import com.careerpilot.modules.interview.service.InterviewSessionService;import com.careerpilot.modules.interview.report.InterviewReportService;import com.careerpilot.security.CurrentUser;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController@RequestMapping("/api/v1/interview-sessions")public class InterviewSessionController{private final InterviewSessionService service;private final InterviewReportService reports;public InterviewSessionController(InterviewSessionService service,InterviewReportService reports){this.service=service;this.reports=reports;}@PostMapping@ResponseStatus(HttpStatus.CREATED)public Session start(@Valid@RequestBody StartRequest request){return service.start(CurrentUser.require(),request);}@PostMapping("/{id}/answers")public Session answer(@PathVariable UUID id,@Valid@RequestBody SubmitAnswerRequest request){return service.answer(CurrentUser.require(),id,request);}@GetMapping("/{id}")public Session get(@PathVariable UUID id){return service.get(CurrentUser.require(),id);}@GetMapping public List<History>history(){return service.history(CurrentUser.require());}@GetMapping("/transcription/status")public TranscriptionStatus transcriptionStatus(){return new TranscriptionStatus(false,"NOT_CONFIGURED","Automatic transcription is not configured. Review and submit a transcript manually; recorded media is not uploaded or stored.");}@GetMapping(value="/{id}/report.pdf",produces=MediaType.APPLICATION_PDF_VALUE)public ResponseEntity<byte[]>report(@PathVariable UUID id){var report=reports.generate(CurrentUser.require(),id);return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\""+report.filename()+"\"").body(report.content());}}
